using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Presentation.MissionShell;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {public sealed class RecurringValidationTests {
 sealed class Journal:IAccountActionJournal {public PendingAccountAction Row;public PendingAccountAction Read(string id)=>Row?.Account==id?Row:null;public bool Save(PendingAccountAction a){Row=a;return true;}public bool Remove(PendingAccountAction a){Row=null;return true;}}
 sealed class Wire:IRunApiHttpTransport {public List<RunApiHttpRequest> Requests=new List<RunApiHttpRequest>();public Func<RunApiHttpRequest,Task<RunApiHttpResponse>> Reply=r=>Task.FromResult(RunApiHttpResponse.NetworkError("lost"));public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest r){Requests.Add(r);return Reply(r);}}
 static GameApiAuthSessionSnapshot Session()=>new GameApiAuthSessionSnapshot("account_test","ACTIVE",new GameApiAccessToken("lst1.fixture"),DateTime.UtcNow.AddMinutes(5),new GameApiRefreshToken("fixture"),DateTime.UtcNow.AddMinutes(10));
 static JObject Empty(string time){var now=DateTimeOffset.Parse(time);var service=now.AddHours(5);var day=new DateTimeOffset(service.Year,service.Month,service.Day,0,0,0,TimeSpan.Zero).AddHours(-5);var start=new DateTimeOffset(service.Year,service.Month,1,0,0,0,TimeSpan.Zero).AddHours(-5);var i=(int)(day-start).TotalDays;return new JObject{["accepted"]=true,["version"]="recurring-v1",["serverTime"]=now.ToUnixTimeMilliseconds(),["progressSyncPending"]=false,["periods"]=new JObject{["cycleId"]=service.ToString("yyyy-MM"),["startAt"]=start.ToUnixTimeMilliseconds(),["endAt"]=start.AddHours(5).AddMonths(1).AddHours(-5).ToUnixTimeMilliseconds(),["dayStart"]=day.ToUnixTimeMilliseconds(),["dayEnd"]=day.AddDays(1).ToUnixTimeMilliseconds(),["weekStart"]=day.AddDays(-(((int)service.DayOfWeek+6)%7)).ToUnixTimeMilliseconds(),["dayIndex"]=i,["passWeek"]=i<28?new JValue(i/7):JValue.CreateNull()},["capabilities"]=new JObject{["ordinaryOperationBinding"]="REQUIRES_EXPLICIT_VERSIONED_MAPPING",["storyDefeat"]="UNSUPPORTED_COST_CONTRACT_PENDING",["cooperativeParticipantProducer"]="NOT_IMPLEMENTED",["cooperativeProgress"]="UNKNOWN_FOR_UNLINKED_ORIGINAL_PARTICIPANTS",["existingOwnerFinishProducer"]=true},["policies"]=new JArray(),["awards"]=new JArray(),["mail"]=new JArray(),["grants"]=new JArray(),["eventStatus"]=new JArray()};}
 [Test] public void EmptyCommandsRequireZeroBytesAndPassClaimsAreStrict(){foreach(var kind in new[]{"recurring-login","recurring-quest","recurring-mail"}){var target=kind=="recurring-login"?"login":"award";Assert.DoesNotThrow(()=>RecurringContract.Endpoint(kind,target,null));Assert.Throws<FormatException>(()=>RecurringContract.Endpoint(kind,target,"{}"));}Assert.Throws<FormatException>(()=>RecurringContract.Endpoint("recurring-pass","policy","{\"level\":51,\"track\":\"FREE\"}"));Assert.Throws<FormatException>(()=>RecurringContract.Endpoint("recurring-pass","policy","{\"level\":1,\"track\":\"FREE\",\"quantity\":100}"));}
 [Test] public async Task UnknownAndMalformedGrantKeepsOriginalAccountRequest(){var journal=new Journal{Row=new PendingAccountAction("account_test","recurring-mail","award",0,"original:/+",null)};var action=journal.Row;var wire=new Wire();var session=Session();using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>1);await state.RetryPendingAsync();wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,"{\"accepted\":true}"));await state.RetryPendingAsync();Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.LastRecurringGrant,Is.Null);Assert.That(wire.Requests.Count,Is.EqualTo(2));Assert.That(wire.Requests.All(r=>r.BodyJson==null&&r.EndpointPath=="/v1/quest-mail/award/claim"&&r.Headers.Single(h=>h.Name=="Idempotency-Key").Value==action.Key),Is.True);}
 [Test] public async Task OwnerSwitchDiscardsLateReplyWithoutDeletingOldJournal(){var journal=new Journal{Row=new PendingAccountAction("account_test","recurring-login","login",0,"old_key",null)};var action=journal.Row;var done=new TaskCompletionSource<RunApiHttpResponse>();var wire=new Wire{Reply=r=>done.Task};var session=Session();long generation=1;using var state=new AccountScreenRuntime(wire,journal,()=>session,()=>generation);var task=state.RetryPendingAsync();generation++;state.SynchronizeSession();done.SetResult(RunApiHttpResponse.Success(200,"{\"accepted\":true,\"eventSource\":\"SERVER_LOGIN\",\"dayStart\":1000,\"refreshRequired\":true}"));await task;Assert.That(journal.Row,Is.SameAs(action));Assert.That(state.Recurring,Is.Null);}
 [Test] public async Task ReadOnlyStateNeverCreatesLoginSyncOrGrants(){var wire=new Wire{Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,Empty("2026-09-10T00:00:00Z").ToString()))};var session=Session();using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1);await state.RefreshRecurringAsync();Assert.That(state.RecurringReady,Is.True,state.RecurringError);Assert.That(wire.Requests.Count,Is.EqualTo(1));Assert.That(wire.Requests[0].Method,Is.EqualTo("GET"));Assert.That(state.CanClaimRecurring("recurring-pass","unknown","{\"level\":1,\"track\":\"PREMIUM\"}"),Is.False);}
 [TestCase("2026-09-28T18:59:59Z",3)][TestCase("2026-09-28T19:00:00Z",-1)][TestCase("2026-09-30T19:00:00Z",0)]
 public void WeeklyAndMonthlyBoundariesUseServerKst04(string time,int week){var r=Empty(time);var state=new RecurringSnapshot(r.ToString(),"account_test");Assert.That((int?)state.Periods["passWeek"]??-1,Is.EqualTo(week));r["periods"]["weekStart"]=(long)r["periods"]["weekStart"]+86400000;Assert.Throws<FormatException>(()=>new RecurringSnapshot(r.ToString(),"account_test"));}
} }
